Assumptions:
1. Airport Ground Capacity: A Semaphore with 3 permits tracks the total planes on grounds (runway + gates).
2. Runway Access: A ReentrantLock (Fairness = true) ensures only one plane uses the runway at a time.
3. Gates: A Semaphore with 2 permits (as the brief mentions 2 gates are occupied in the congested scenario) manages docking.
4. Fuel Truck: A single Semaphore with 1 permit ensures exclusive refuelling.
5. Emergency Landing: A high-priority queue or interrupted thread logic will handle the fuel shortage plane.

[REQUIRES STUDENT'S OWN EVIDENCE: Video file showing the simulation output and meeting all requirements]

```java
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;

class Airport {
    final Semaphore groundCapacity = new Semaphore(3);
    final ReentrantLock runway = new ReentrantLock(true);
    final Semaphore gates = new Semaphore(2);
    final Semaphore fuelTruck = new Semaphore(1);

    AtomicInteger totalServed = new AtomicInteger(0);
    AtomicInteger totalPassengers = new AtomicInteger(0);
    CopyOnWriteArrayList<Long> waitTimes = new CopyOnWriteArrayList<>();

    void simulatePlane(String name, boolean emergency) {
        long arrivalTime = System.currentTimeMillis();
        try {
            if (emergency) System.out.println(name + " REQUESTING EMERGENCY LANDING!");

            groundCapacity.acquire();
            runway.lock();
            System.out.println(name + " landing on runway.");
            Thread.sleep(500); // Simulate landing
            runway.unlock();

            gates.acquire();
            System.out.println(name + " docked at gate.");

            // Concurrent disembark, cleaning, supplies
            Thread t1 = new Thread(() -> task(name + " disembarking"));
            Thread t2 = new Thread(() -> task(name + " cleaning/supplies"));
            t1.start(); t2.start();

            // Exclusive refueling
            fuelTruck.acquire();
            System.out.println(name + " refueling.");
            Thread.sleep(500);
            fuelTruck.release();

            t1.join(); t2.join();

            System.out.println(name + " leaving gate.");
            gates.release();

            runway.lock();
            System.out.println(name + " taking off.");
            Thread.sleep(500);
            runway.unlock();

            groundCapacity.release();
            waitTimes.add(System.currentTimeMillis() - arrivalTime);
            totalServed.incrementAndGet();
            totalPassengers.addAndGet(50); // Assume 50 per plane
        } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }

    private void task(String desc) {
        try { Thread.sleep(300); System.out.println(desc + " completed."); }
        catch (InterruptedException e) {}
    }
}
